$$("[data-goto]").forEach(b=>b.onclick=()=>setView(b.dataset.goto));$$("[data-action=newjob]").forEach(b=>b.onclick=()=>openJob());$$("[data-action=adddevice]").forEach(b=>b.onclick=()=>openDevice());$$("[data-detail]").forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));
if($("#jobSearch")){$("#jobSearch").oninput=renderJobs;$("#jobFilter").onchange=renderJobs;$("#jobSort").onchange=renderJobs;["jobDevice","jobDebt","jobFrom","jobTo"].forEach(id=>{const el=$("#"+id);el.onchange=renderJobs;el.oninput=renderJobs});renderJobs()}
if($("#customerSearch"))$("#customerSearch").oninput=()=>{const q=norm($("#customerSearch").value).toLowerCase();$$("[data-customer-row]").forEach(r=>r.classList.toggle("hidden",!r.dataset.customerRow.includes(q)))};
$$("[data-history]").forEach(b=>b.onclick=()=>{const k=norm(b.dataset.history);openHistory(b.dataset.history,jobs.filter(j=>norm(j.customerPhone||"")===k||j.customerName===b.dataset.history))});
