if($("#settingsForm"))$("#settingsForm").onsubmit=async e=>{e.preventDefault();settings={...settings,...Object.fromEntries(new FormData(e.target).entries())};settings.currencyUnit=settings.currencyUnit==="rial"?"rial":"toman";await RepairDB.put("settings",{id:"main",value:settings});$("#shopMini").textContent=settings.shopName;await refresh();toast("تنظیمات ذخیره شد.")};
if($("#copyDev"))$("#copyDev").onclick=()=>copyText(RDLicense.state.device);if($("#activateLic"))$("#activateLic").onclick=async()=>{const r=await RDLicense.activate($("#licCode").value);toast(r.ok?"مجوز با موفقیت فعال شد.":r.reason);if(r.ok)render()};if($("#resetAll"))$("#resetAll").onclick=async()=>{if(prompt("برای تأیید حذف کامل داده‌ها، کلمه «حذف» را بنویسید:")!=="حذف")return;await RepairDB.replaceAll({});await refresh();toast("همه داده‌ها پاک شد.")};if($("#exportBackup"))$("#exportBackup").onclick=exportBackup;if($("#importBackup"))$("#importBackup").onclick=importBackup;if(view==="finance")bindFinance();
